-- Extend existing Prompt Master without changing old templates/history/URLs.
ALTER TABLE "PromptTemplate" ADD COLUMN "showcase" TEXT NOT NULL DEFAULT '{}';
ALTER TABLE "PromptTemplate" ADD CONSTRAINT "PromptTemplate_showcase_check" CHECK (length("showcase") <= 40000 AND jsonb_typeof("showcase"::jsonb) = 'object');
ALTER TABLE "PromptTemplate" DROP CONSTRAINT "PromptTemplate_kind_check";
ALTER TABLE "PromptTemplate" ADD CONSTRAINT "PromptTemplate_kind_check" CHECK ("kind" IN ('TEXT','IMAGE','VIDEO','CODE','WEB'));
ALTER TABLE "PromptGeneration" DROP CONSTRAINT "PromptGeneration_kind_check";
ALTER TABLE "PromptGeneration" ADD CONSTRAINT "PromptGeneration_kind_check" CHECK ("kind" IN ('TEXT','IMAGE','VIDEO','CODE','WEB'));
INSERT INTO "PromptTemplate" ("slug","title","summary","kind","category","tags","content","example","defaults","showcase","status","featured","sortOrder","publishedAt") VALUES ('design-blueprint-gt','وقتی اسکچ مهندسی جان می‌گیرد','از خطوط دقیق مداد تا رندر واقع‌گرایانهٔ یک گرندتورر مفهومی؛ روی کاغذی با بافت واقعی.','IMAGE','DESIGN','خودرو، بلوپرینت، طراحی صنعتی، رندر سه‌بعدی','برای این ایده یک دستور دقیق و قابل استفاده بساز:
{{idea}}
قالب و سبک نمونه را با نیاز کاربر سازگار کن.','Original portfolio sample image for a professional prompt gallery. A beautiful detailed automotive concept study of an original unbranded pearl white electric grand-tourer, no existing brand logo, shown in front three-quarter view as photorealistic 3D rendering, surrounded by delicate pencil technical sketch orthographic views, wheel and suspension sketches, thin dimension lines and tiny plausible engineering annotations. Warm ivory drafting paper, precise graphite lines, restrained blue accents. Editorial automobile design studio quality, natural shadows, rich tactile paper, not a website screenshot. Landscape 4:3 composition with the car filling the frame. Only a tiny neutral heading ''GT / 01''. No watermark. This is a fictional design study, not specifications of a real vehicle.','{"language":"en","ratio":"4:3"}','{"cover":"/images/prompts/blueprint.webp","video":"","alt":"رندر گرندتورر سفید میان اسکچ‌های فنی روی کاغذ کرم","caption":"مطالعهٔ طراحی خیالی؛ اندازه‌ها مشخصات فنی یک خودروی واقعی نیستند.","credit":"تصویر اختصاصی موبوکام؛ ساخته‌شده با ابزار تولید تصویر","result":"","webLayout":"none","aspect":"wide"}','PUBLISHED',true,-100,now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "PromptTemplate" ("slug","title","summary","kind","category","tags","content","example","defaults","showcase","status","featured","sortOrder","publishedAt") VALUES ('sketchbook-character','شخصیت سه‌بعدی در دفتر خاطرات','بافت نرم لباس، نور لطیف و جزئیات دوست‌داشتنی در یک کلاژ شخصیتی گرم و صمیمی.','IMAGE','DESIGN','شخصیت، سه‌بعدی، کلاژ، تصویرسازی','برای این ایده یک دستور دقیق و قابل استفاده بساز:
{{idea}}
قالب و سبک نمونه را با نیاز کاربر سازگار کن.','Original portfolio sample image for a professional prompt gallery. Charming high quality stylized 3D illustration of a young adult woman with short dark wavy hair, amber round glasses, oversized soft terracotta cardigan holding a ceramic cup, expressive thoughtful smile. Cream sketchbook collage backdrop with handwritten-style line doodles of a sleeping cat, tiny plants, coffee beans and torn paper notes. Premium animated-film character design with tactile fabrics, soft volumetric studio lighting, moss and burnt-orange palette, not derived from any specific existing character. Clean cohesive portrait 3:4 framing. No text except tiny decorative simple marks, no watermark. A visual character concept, not a UI screenshot.','{"language":"en","ratio":"3:4"}','{"cover":"/images/prompts/character.webp","video":"","alt":"شخصیت سه‌بعدی با عینک و فنجان قهوه در کلاژ دفتر طراحی","caption":"نمونهٔ اصلی طراحی شخصیت؛ برای چهرهٔ واقعی به مرجع دارای مجوز نیاز دارید.","credit":"تصویر اختصاصی موبوکام؛ ساخته‌شده با ابزار تولید تصویر","result":"","webLayout":"none","aspect":"portrait"}','PUBLISHED',true,-99,now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "PromptTemplate" ("slug","title","summary","kind","category","tags","content","example","defaults","showcase","status","featured","sortOrder","publishedAt") VALUES ('amber-perfume-editorial','نور طلایی، شیشهٔ کهربایی','عکاسی محصول با سنگ روشن، شکست نور و یک روایت مینیمال از رایحهٔ مرکبات.','IMAGE','DESIGN','محصول، عطر، عکاسی، نورپردازی','برای این ایده یک دستور دقیق و قابل استفاده بساز:
{{idea}}
قالب و سبک نمونه را با نیاز کاربر سازگار کن.','Original portfolio sample image for a professional prompt gallery. Luxury editorial product photograph of a simple unbranded amber glass perfume bottle with brushed brass cap on sculptural pale limestone, translucent citrus slices and a single dried botanical sprig, warm late afternoon side-light refracting through glass, evocative subtle caustics and strong crisp shadow, beige sand and burnt orange color story, cinematic macro lens detail and elevated art direction. No typography, no labels, no logos or watermark. Square composition, beautiful realistic glass, commercially polished still life.','{"language":"en","ratio":"1:1"}','{"cover":"/images/prompts/perfume.webp","video":"","alt":"بطری عطر کهربایی کنار مرکبات روی سنگ آهکی در نور گرم","caption":"تصویر نمونه با پرامپت همین صفحه ساخته شده؛ محصول و برند واقعی معرفی نمی‌شود.","credit":"تصویر اختصاصی موبوکام؛ ساخته‌شده با ابزار تولید تصویر","result":"","webLayout":"none","aspect":"square"}','PUBLISHED',true,-98,now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "PromptTemplate" ("slug","title","summary","kind","category","tags","content","example","defaults","showcase","status","featured","sortOrder","publishedAt") VALUES ('orbit-motion-study','مدار نور؛ مطالعهٔ حرکت و ریتم','یک موشن کوتاهِ بی‌صدا با مدارهای نورانی، عمق میدان و حرکت آرام در فضای تاریک.','VIDEO','VIDEO','ویدئو، موشن، نور، حرکت','برای این ایده یک دستور دقیق و قابل استفاده بساز:
{{idea}}
قالب و سبک نمونه را با نیاز کاربر سازگار کن.','یک موشن گرافیک شش‌ثانیه‌ای و بی‌صدا طراحی کن: کرهٔ نورانی فیروزه‌ای در مرکز صحنهٔ تاریک، حلقه‌های بنفش و فیروزه‌ای در مدارهای مایل با حرکت نرم، ذرات کم‌تعداد، درخشش کنترل‌شده و کادر عریض. حرکت یکنواخت و پایان نزدیک به شروع باشد. هیچ نوشته، برش تند یا فلاش روشن نداشته باشد.','{"ratio":"16:9","duration":"5","style":"موشن سه‌بعدی انتزاعی؛ حرکت آرام و نور کنترل‌شده"}','{"cover":"/images/prompts/orbit.webp","video":"/images/prompts/orbit.webm","alt":"مدارهای بنفش و فیروزه‌ای دور کره‌ای نورانی","caption":"نمونهٔ شش‌ثانیه‌ای بدون صدا برای نمایش حرکت پیشنهادی.","credit":"موشن نمونهٔ تألیفی موبوکام با Canvas؛ خروجی یک مدل ویدئویی نیست","result":"","webLayout":"none","aspect":"wide"}','PUBLISHED',true,-97,now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "PromptTemplate" ("slug","title","summary","kind","category","tags","content","example","defaults","showcase","status","featured","sortOrder","publishedAt") VALUES ('slow-coffee-story','یک فنجان، کمی آهسته‌تر','نمونهٔ متن روایی کوتاه؛ تصویرسازی با کلمات، بدون شعار و ادعاهای ساختگی.','TEXT','WRITING','داستان، قهوه، نگارش، روایت','برای این ایده یک دستور دقیق و قابل استفاده بساز:
{{idea}}
قالب و سبک نمونه را با نیاز کاربر سازگار کن.','برای یک کافهٔ کوچک، متنی روایی و کوتاه دربارهٔ مکث‌کردن در شروع روز بنویس. با یک جزئیات حسی شروع کن، لحن گرم و آرام داشته باش، سه بند کوتاه بنویس و بدون شعار تبلیغاتی با یک دعوت ساده تمام کن. ویژگی یا آمار تأییدنشده به کسب‌وکار نسبت نده.','{"tone":"صمیمی"}','{"cover":"","video":"","alt":"","caption":"نمونهٔ پاسخ برای نشان‌دادن لحن و ساختار؛ ادعای خروجی یک مدل مشخص ندارد.","credit":"نمونهٔ نگارش تألیفی موبوکام","result":"صبح، پیش از آن‌که خیابان شلوغ شود، بخار از لبهٔ فنجان بالا می‌رود. نور پنجره روی میز می‌نشیند و برای چند لحظه، هیچ کاری فوری نیست.\n\nفنجان را با دو دست بگیر. به گرمایش فرصت بده؛ به صدای آرام قاشق، به بوی قهوه، به فکری که هنوز جمله نشده است.\n\nامروز را کمی آهسته‌تر شروع کنیم. اگر گذرت افتاد، یک صندلی کنار پنجره هست.","webLayout":"none","aspect":"portrait"}','PUBLISHED',true,-96,now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "PromptTemplate" ("slug","title","summary","kind","category","tags","content","example","defaults","showcase","status","featured","sortOrder","publishedAt") VALUES ('atelier-web-landing','استودیوی خلاق؛ وب‌سایتی با امضا','یک لندینگ با تایپوگرافی درشت، فضای تنفس و ترکیب‌بندی تحریریه‌ای برای استودیوی طراحی.','WEB','DEVELOPMENT','وب، لندینگ، پورتفولیو، طراحی رابط','برای این ایده یک دستور دقیق و قابل استفاده بساز:
{{idea}}
قالب و سبک نمونه را با نیاز کاربر سازگار کن.','Design a responsive editorial landing page for an independent creative studio called ATELIER. Use warm ivory, dark forest green and a restrained lime accent. Combine oversized serif headlines, generous negative space, a compact navigation and a curated project grid. Include a clear contact call to action, visible keyboard focus and a stacked mobile layout. Use reusable components and accessible semantic HTML. Do not invent client endorsements or business metrics.','{"language":"en","target":"Claude","style":"Editorial, warm ivory and forest green"}','{"cover":"","video":"","alt":"","caption":"پیش‌نمایش ساختاری امن از جهت طراحی این پرامپت؛ کد دلخواه در سایت اجرا نمی‌شود.","credit":"نمونهٔ چیدمان تألیفی موبوکام","result":"<main class=\"studio\">\n  <header><a href=\"/\">ATELIER.</a><nav aria-label=\"Main navigation\">Work · About · Contact</nav></header>\n  <section aria-labelledby=\"studio-title\">\n    <p>INDEPENDENT DESIGN STUDIO</p>\n    <h1 id=\"studio-title\">Ideas made tangible.</h1>\n    <p>Identity, digital experiences and considered design.</p>\n  </section>\n</main>","webLayout":"landing","aspect":"wide"}','PUBLISHED',true,-95,now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "PromptTemplate" ("slug","title","summary","kind","category","tags","content","example","defaults","showcase","status","featured","sortOrder","publishedAt") VALUES ('pulse-web-dashboard','داشبوردی که شلوغی را آرام می‌کند','نمای مدیریت پروژه با سلسله‌مراتب روشن، خلاصهٔ وضعیت و تایپوگرافی خوانا.','WEB','DEVELOPMENT','وب، داشبورد، محصول، رابط کاربری','برای این ایده یک دستور دقیق و قابل استفاده بساز:
{{idea}}
قالب و سبک نمونه را با نیاز کاربر سازگار کن.','Create a responsive project-management dashboard concept named PULSE. Use a calm slate canvas, white cards and small violet accents. Show a clear workspace sidebar, a recent-project list and a simple weekly activity chart using explicitly illustrative sample data. Prioritize readable labels, visual hierarchy, keyboard access, empty/error states and a usable narrow-screen layout. Avoid invented claims about real customers or revenue.','{"language":"en","target":"v0","style":"Calm product UI, slate and violet"}','{"cover":"","video":"","alt":"","caption":"داده‌های داخل پیش‌نمایش صرفاً برای نمایش طرح‌اند و آمار واقعی سایت نیستند.","credit":"نمونهٔ رابط و دادهٔ نمایشی موبوکام","result":"<main class=\"workspace\">\n  <aside aria-label=\"Workspace navigation\">PULSE · Overview · Projects</aside>\n  <section aria-labelledby=\"overview-title\">\n    <h1 id=\"overview-title\">Project overview</h1>\n    <p>Illustrative workspace data</p>\n    <ul aria-label=\"Recent projects\"><li>Brand system</li><li>Product website</li><li>Research notes</li></ul>\n  </section>\n</main>","webLayout":"dashboard","aspect":"wide"}','PUBLISHED',true,-94,now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "PromptTemplate" ("slug","title","summary","kind","category","tags","content","example","defaults","showcase","status","featured","sortOrder","publishedAt") VALUES ('accessible-form-component','فرم ساده، جزئیات درست','نمونهٔ یک فیلد دسترس‌پذیر با برچسب، توضیح و خطای متصل؛ برای شروع یک رابط قابل اعتماد.','CODE','DEVELOPMENT','کد، React، دسترس‌پذیری، فرم','برای این ایده یک دستور دقیق و قابل استفاده بساز:
{{idea}}
قالب و سبک نمونه را با نیاز کاربر سازگار کن.','یک کامپوننت کوچک React و TypeScript برای فیلد ایمیل بنویس. برچسب واقعی، توضیح اختیاری و پیام خطای مرتبط با aria-describedby داشته باشد. از شناسهٔ پایدار استفاده کن، فیلد کنترل‌شده باشد و هیچ وابستگی تازه‌ای اضافه نکن. کد را کوتاه نگه دار و توضیح بده اعتبارسنجی نهایی روی سرور انجام می‌شود.','{"format":"کد همراه توضیح"}','{"cover":"","video":"","alt":"","caption":"الگوی آموزشی؛ اعتبارسنجی و مجوز عملیات نهایی در سرور لازم است.","credit":"نمونهٔ کد تألیفی موبوکام","result":"import { useId } from \"react\"\n\nexport function EmailField({ value, error, onChange }: {\n  value: string; error?: string; onChange: (value: string) => void\n}) {\n  const id = useId()\n  return <div>\n    <label htmlFor={id}>ایمیل</label>\n    <input id={id} type=\"email\" autoComplete=\"email\" value={value}\n      onChange={event => onChange(event.target.value)}\n      aria-invalid={!!error} aria-describedby={error ? id + \"-error\" : undefined} />\n    {error && <p id={id + \"-error\"} role=\"alert\">{error}</p>}\n  </div>\n}","webLayout":"none","aspect":"portrait"}','PUBLISHED',true,-93,now()) ON CONFLICT ("slug") DO NOTHING;
